CREATE OR REPLACE FUNCTION public.bi_kpi_conta_concluintes(filtro jsonb)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
    contador integer;
    p_where  varchar;
    p_query  varchar := 'select count(*) ' ||
                        'from tb_evento_corridas eve inner join tb_resultados res on ' ||
                        'res.id_evento = eve.id_evento';
begin

   p_where  := bi_cria_filtro(filtro);
   p_query  := concat(p_query,p_where,' and eve.homologado = true and res.homologado = true and res.concluinte = true ');

   --RAISE exception 'Value: %', p_sql;

    EXECUTE p_query  INTO contador;

    return contador;
end;
$function$

CREATE OR REPLACE FUNCTION public.bi_kpi_conta_eventos(filtro jsonb)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
    contador integer;
    p_where  varchar;
    p_query  varchar := 'select count(distinct eve.id_evento) ' ||
                        'from tb_evento_corridas eve inner join tb_resultados res on ' ||
                        'res.id_evento = eve.id_evento';
begin

   p_where  := bi_cria_filtro(filtro);
   p_query  := concat(p_query,p_where);

   --RAISE exception 'Value: %', p_sql;

    EXECUTE p_query  INTO contador;

    return contador;
end;
$function$

CREATE OR REPLACE FUNCTION public.bi_tab_lista_topnpace(filtro jsonb, p_top integer)
 RETURNS json
 LANGUAGE plpgsql
AS $function$
declare
    ret_json json;
    p_query  varchar := 'select nome, pace ' ||
                    'from tb_evento_corridas eve inner join tb_resultados res on ' ||
                    'res.id_evento = eve.id_evento ';
begin
   p_query := concat(p_query, bi_cria_filtro(filtro), ' order by pace limit ', p_top);
   p_query := concat('select json_agg(row_to_json(linha)) from (', p_query,') linha');

   EXECUTE p_query into ret_json;

   return ret_json;
end;
$function$

CREATE OR REPLACE FUNCTION public.business_delegation_capabilities_valid(proposal jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb; codes text[] := ARRAY[]::text[]; code text;
BEGIN
 IF proposal IS NULL OR jsonb_typeof(proposal)<>'array' THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(proposal) LOOP
  IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF;
  code=item#>>'{}';
  IF code=ANY(codes) OR code NOT IN('ads.campaigns.view','ads.campaigns.manage','ads.payments.view','ads.credits.purchase','events.view','events.manage','events.links.request')
   OR NOT EXISTS(SELECT 1 FROM public.tb_business_permissoes WHERE codigo=code) THEN RETURN false; END IF;
  codes=array_append(codes,code);
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_perfilrun_links_limite()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1
    FROM public.tb_paginas
    WHERE id_pagina = NEW.id_pagina
    FOR UPDATE;

    IF (
        SELECT count(*)
        FROM public.tb_perfilrun_links
        WHERE id_pagina = NEW.id_pagina
    ) >= 30 THEN
        RAISE EXCEPTION 'perfilrun_links_limit_exceeded'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$function$
